"use strict";
// A class at module scope that extends Promise, which the native compiler
// refuses, so the package runs in a Node island and its declarations type
// island values.
class MemberPromise extends Promise {}
exports.MemberPromise = MemberPromise;
exports.VERSION = "1.2.3";
exports.makeTable = () => new Map([["island", 7]]);
exports.makeTags = () => new Set(["island", "tag"]);
exports.makeBytes = () => new Uint8Array([1, 2, 3]);
exports.makeNames = () => ["island"];
exports.makeGauge = () => ({ level: 7, label: "island" });
exports.makeMeta = () => ({ made: "island" });
exports.describe = (value) => JSON.stringify(value);
